using System;using System.IO;using System.Collections;using System.Collections.Generic;using System.Web.Script.Serialization;using ESRI.ArcGIS;using ESRI.ArcGIS.Carto;using ESRI.ArcGIS.Geodatabase;using ESRI.ArcGIS.DataSourcesRaster;using ESRI.ArcGIS.esriSystem;
public static class NativePortable{
 [System.Runtime.InteropServices.DllImport("user32.dll")] static extern IntPtr GetDesktopWindow();
 public static void Run(string folder,string report){RuntimeManager.Bind(ProductCode.Desktop);IAoInitialize lic=new AoInitializeClass();var status=lic.Initialize(esriLicenseProductCode.esriLicenseProductCodeAdvanced);if(status!=esriLicenseStatus.esriLicenseCheckedOut&&status!=esriLicenseStatus.esriLicenseAlreadyInitialized)throw new Exception("License unavailable");JavaScriptSerializer js=new JavaScriptSerializer();js.MaxJsonLength=Int32.MaxValue;string prefix=System.IO.Path.GetFullPath(System.IO.Path.Combine(folder,"data")).TrimEnd('\\')+"\\";var docs=new ArrayList();bool all=true;
 foreach(string file in Directory.GetFiles(folder,"*.mxd")){IMapDocument d=new MapDocumentClass();d.Open(file,"");for(int i=0;i<d.MapCount;i++)((IActiveView)d.get_Map(i)).Activate(GetDesktopWindow().ToInt32());((IActiveView)d.PageLayout).Activate(GetDesktopWindow().ToInt32());var layers=new ArrayList();int broken=0,external=0;for(int i=0;i<d.MapCount;i++){IMap m=d.get_Map(i);for(int j=0;j<m.LayerCount;j++){ILayer l=m.get_Layer(j);bool valid=l.Valid;if(!valid)broken++;string source="";if(l is IFeatureLayer){var fc=((IFeatureLayer)l).FeatureClass;if(fc!=null)source=((IDataset)fc).Workspace.PathName;}else if(l is IRasterLayer){var raster=((IRasterLayer)l).Raster as IRaster2;if(raster!=null&&raster.RasterDataset!=null){IDataset ds=(IDataset)raster.RasterDataset;source=System.IO.Path.Combine(ds.Workspace.PathName,ds.Name);}}bool local=source!=""&&System.IO.Path.GetFullPath(source).StartsWith(prefix,StringComparison.OrdinalIgnoreCase);if(!local)external++;layers.Add(new{map=m.Name,layer=l.Name,valid=valid,source=source,within_copied_data=local});}}bool ok=broken==0&&external==0;all=all&&ok;docs.Add(new{file=file,status=ok?"PASS":"FAIL",maps=d.MapCount,broken=broken,external_sources=external,layers=layers});d.Close();Console.WriteLine((ok?"PASS ":"FAIL ")+file);}
 File.WriteAllText(report,js.Serialize(new{status=all?"PASS":"FAIL",engine="Native ArcObjects Desktop10.8",copied_folder=folder,source_constraint=prefix,documents=docs}));lic.Shutdown();if(!all)throw new Exception("Portable references failed; see report");}
}
